import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] A = new int[2 * n];
        for (int i = 0; i < 2 * n; i++) {
            A[i] = sc.nextInt();
        }
        int count = 0;
        for (int i = 1; i <= n; i++) {
            int firstIndex = -1;
            int secondIndex = -1;
            for (int j = 0; j < 2 * n; j++) {
                if (A[j] == i) {
                    if (firstIndex == -1) {
                        firstIndex = j;
                    } else {
                        secondIndex = j;
                        break;
                    }
                }
            }
            if (secondIndex - firstIndex == 2) {
                count++;
            }
        }
        System.out.print(count);
    }
}
